    print('%s: old %d entries, new %d entries; names equal: %s; entries whose bytes differ: %d %s' % (
        p, len(a), len(b), set(a) == set(b), sum(1 for k in a if k in b and a[k] != b[k]),
        sorted(k for k in a if k in b and a[k] != b[k])[:5]))
    print('  only old:', sorted(set(a) - set(b))[:10], ' only new:', sorted(set(b) - set(a))[:10])
